uses Controls,GraphWPF;

begin
  Window.Title := 'Calculator with TextBox output';
  LeftPanel(150, Colors.Orange);
  var tb := SetMainControl.AsTextBox;
  tb.FontSize := 30;
  var x := IntegerBox('X:');
  var y := IntegerBox('Y:');
  x.Value := Random(0,10);
  y.Value := Random(0,10);

  var cb := new ComboBoxWPF('Operation');
  cb.AddRange('+','-','*','/');

  var count := 0;
  var sb := StatusBar;
  sb.Text := 'Calculation count: ' + count;

  var b := Button('+');
  b.Click := procedure -> begin
    case cb.SelectedText of
      '+': tb.Println($'{x.Value} + {y.Value} = {x.Value + y.Value}');
      '-': tb.Println($'{x.Value} - {y.Value} = {x.Value - y.Value}');
      '*': tb.Println($'{x.Value} * {y.Value} = {x.Value * y.Value}');
      '/': tb.Println($'{x.Value} / {y.Value} = {x.Value / y.Value}');
    end;
    x.Value := Random(0,10);
    y.Value := Random(0,10);
    count += 1;
    sb.Text := 'Calculation count: ' + count;
  end;

  Button('Clear').Click := () -> begin
    count := 0;
    sb.Text := 'Calculation count: ' + count;
    tb.Clear;
  end;

  cb.SelectionChanged := procedure -> begin
    b.Text := cb.SelectedText
  end;
end.

